import subprocess, os
def run(args, input_data=None, env=None):
    import subprocess
    e=os.environ.copy()
    if env: e.update(env)
    return subprocess.run(args, input=input_data, capture_output=True, text=True, env=e)

# alignment needs wider columns to see effect
csv="longheader,b,c\n1,2,3\n4,5,6\n"
for ha in ["left","center","right"]:
    for ba in ["left","center","right"]:
        r=run(["./executable","-P",f"--header-align={ha}",f"--body-align={ba}"], input_data=csv)
        print(f"=== ha={ha} ba={ba} ===")
        print(r.stdout,end="")

# more revealing: headers short, bodies long
csv2="a,b,c\nlongvalue1,2,3\n4,5,6\n"
for ba in ["left","center","right"]:
    r=run(["./executable","-P",f"--body-align={ba}"], input_data=csv2)
    print(f"=== body {ba} with long body ===")
    print(r.stdout,end="")
for ha in ["left","center","right"]:
    r=run(["./executable","-P",f"--header-align={ha}"], input_data="longheader,bb,cc\n1,2,3\n")
    print(f"=== header {ha} ===")
    print(r.stdout,end="")
    for line in r.stdout.splitlines():
        print(repr(line))
