// Minimal terminal_size implementation for offline build
// Provides same API as terminal_size 0.4.3: terminal_size() -> Option<(Width, Height)>
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

pub fn terminal_size() -> Option<(Width, Height)> {
    // Try to get terminal size via ioctl on stdout, stderr, stdin
    // If none are ttys, return None (clap will fallback to COLUMNS env or 100)
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        // Try stdout (1), stderr (2), stdin (0)
        for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
            if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 {
                if ws.ws_col != 0 && ws.ws_row != 0 {
                    return Some((Width(ws.ws_col), Height(ws.ws_row)));
                }
            }
        }
    }
    None
}
RS
