#[derive(Clone, Copy, PartialEq, Eq)]
enum Align { Left, Center, Right }
impl Align {
    fn from_str(s: &str) -> Self {
        match s.to_ascii_lowercase().as_str() {
            "left" => Align::Left,
            "right" => Align::Right,
            _ => Align::Center,
        }
    }
}

fn align_and_pad(s: &str, width: usize, align: Align) -> String {
    let (trunc, trunc_w) = s.unicode_truncate(width);
    let pad_needed = width.saturating_sub(trunc_w);
    let (left_extra, right_extra) = match align {
        Align::Left => (0, pad_needed),
        Align::Right => (pad_needed, 0),
        Align::Center => {
            let left = pad_needed / 2;
            let right = pad_needed - left;
            (left, right)
        }
    };
    let mut out = String::with_capacity(trunc.len() + pad_needed);
    for _ in 0..left_extra { out.push(' '); }
    out.push_str(trunc);
    for _ in 0..right_extra { out.push(' '); }
    out
}

