fn build_row_helper(fields: &[String], aligns: &[Align], widths: &[usize], borders: &Borders, indent_str: &str, padding: usize) -> String {
    let mut s = String::new();
    s.push_str(indent_str);
    s.push_str(borders.row_left);
    for (idx, ((field, align), w)) in fields.iter().zip(aligns.iter()).zip(widths.iter()).enumerate() {
        if idx > 0 { s.push_str(borders.row_mid); }
        let aligned = align_and_pad(field, *w, *align);
        for _ in 0..padding { s.push(' '); }
        s.push_str(&aligned);
        for _ in 0..padding { s.push(' '); }
